// mutateRootSummary reads the root CheckpointSummary at rootMetadataPath from
// entries, applies fn to it, and writes the re-marshaled blob back into entries.
// Mirrors mutateSessionMetadata for the root metadata.json.
func (s *GitStore) mutateRootSummary(rootMetadataPath string, entries map[string]object.TreeEntry, fn func(*CheckpointSummary)) error {
	entry, exists := entries[rootMetadataPath]
	if !exists {
		return fmt.Errorf("checkpoint summary not found at %s", rootMetadataPath)
	}

	summary, err := s.readSummaryFromBlob(entry.Hash)
	if err != nil {
		return fmt.Errorf("read checkpoint summary: %w", err)
	}
	fn(summary)

	summaryJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal checkpoint summary: %w", err)
	}
	summaryHash, err := CreateBlobFromContent(s.repo, summaryJSON)
	if err != nil {
		return err
	}
	entries[rootMetadataPath] = object.TreeEntry{
		Name: rootMetadataPath,
		Mode: filemode.Regular,
		Hash: summaryHash,
	}
	return nil
}

